    <div class="shop-tabs" role="tablist" aria-label="Разделы магазина"><button id="skins-tab" role="tab" data-shop-tab="skins" aria-controls="catalog-panel">Костюмы</button><button id="pets-tab" role="tab" data-shop-tab="pets" aria-controls="catalog-panel">Питомцы</button><button id="parkour-tab" role="tab" data-shop-tab="parkour" aria-controls="parkour-panel">${ms} Паркур</button></div>
